1	// Acceptance tests for the change request:
2	//   "Let me mark a project as active, on hold or finished. Show which it is."
3	//
4	// A project now carries a STATUS — one of active, on hold or finished. The projects list shows,
5	// alongside each project's name and client, WHICH status it is (project-status, a cell in the
6	// project row, like the invoice list shows invoice-status). The add-a-project form lets the owner
7	// PICK that status when creating the project (project-form-status), and the project then shows the
8	// status that was picked — not a fixed default.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
11	// projects: { id, clientId, name, status } (alongside clients) — `status` seeds a project directly
12	// into one of the three states so the display can be checked without a click; the pick-a-status flow
13	// is driven through the existing project form. This change records nothing, so no audit channel is
14	// used.
15	//
16	// The three states are the change request's own words ("active", "on hold", "finished"), asserted
17	// VOCABULARY- and CASING-tolerantly so whichever wording/casing the feature renders passes (the
18	// invoice-status specs do the same). Each state is matched by the one token that distinguishes it,
19	// and every status cell is also asserted NOT to read as either of the other two — so a project that
20	// shows the WRONG status (a leaked default, a mislabelled cell) fails rather than passing on a loose
21	// match. This SHOULD FAIL before the change: a project row carries no project-status cell today, and
22	// the add form has no project-form-status control.
23	import { test, expect, type Locator } from '@playwright/test';
24	import { resetAndSeed } from '../support/seed';
25	
26	// The distinguishing token for each state. Mutually exclusive: "active" carries only ACTIVE,
27	// "on hold" only HOLD, "finished" only FINISHED — so each can be told apart from the other two.
28	const ACTIVE = /active/i;
29	const HOLD = /hold/i;
30	const FINISHED = /finish|complete|done/i;
31	
32	// Pick the option in the status dropdown whose visible text matches `re`, selecting it by its value
33	// (so the exact label casing/wording the feature chose does not have to be known up front).
34	async function pickStatus(select: Locator, re: RegExp): Promise<void> {
35	  const options = select.locator('option');
36	  const count = await options.count();
37	  for (let i = 0; i < count; i++) {
38	    const option = options.nth(i);
39	    const text = (await option.textContent())?.trim() ?? '';
40	    if (re.test(text)) {
41	      const value = await option.getAttribute('value');
42	      await select.selectOption(value !== null ? value : { label: text });
43	      return;
44	    }
45	  }
46	  throw new Error(`no status option matching ${re} in project-form-status`);
47	}
48	
49	test.describe('mark a project as active, on hold or finished', () => {
50	  test('lists each project showing which status it is', async ({ page }) => {
51	    await resetAndSeed({
52	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
53	      projects: [
54	        { id: 1, clientId: 1, name: 'Website redesign', status: 'active' },
55	        { id: 2, clientId: 1, name: 'Warehouse automation', status: 'on hold' },
56	        { id: 3, clientId: 1, name: 'Mobile app', status: 'finished' },
57	      ],
58	    });
59	
60	    await page.goto('/projects');
61	    await expect(page.getByTestId('projects-page')).toBeVisible();
62	    await expect(page.getByTestId('projects-table')).toBeVisible();
63	
64	    // Project 1 is active — and reads as active, not as on hold or finished.
65	    const active = page.getByTestId('project-row-1');
66	    await expect(active).toBeVisible();
67	    await expect(active.getByTestId('project-name')).toHaveText('Website redesign');
68	    await expect(active.getByTestId('project-status')).toContainText(ACTIVE);
69	    await expect(active.getByTestId('project-status')).not.toContainText(HOLD);
70	    await expect(active.getByTestId('project-status')).not.toContainText(FINISHED);
71	
72	    // Project 2 is on hold — and reads as on hold, not active or finished.
73	    const onHold = page.getByTestId('project-row-2');
74	    await expect(onHold).toBeVisible();
75	    await expect(onHold.getByTestId('project-name')).toHaveText('Warehouse automation');
76	    await expect(onHold.getByTestId('project-status')).toContainText(HOLD);
77	    await expect(onHold.getByTestId('project-status')).not.toContainText(ACTIVE);
78	    await expect(onHold.getByTestId('project-status')).not.toContainText(FINISHED);
79	
80	    // Project 3 is finished — and reads as finished, not active or on hold.
81	    const finished = page.getByTestId('project-row-3');
82	    await expect(finished).toBeVisible();
83	    await expect(finished.getByTestId('project-name')).toHaveText('Mobile app');
84	    await expect(finished.getByTestId('project-status')).toContainText(FINISHED);
85	    await expect(finished.getByTestId('project-status')).not.toContainText(ACTIVE);
86	    await expect(finished.getByTestId('project-status')).not.toContainText(HOLD);
87	  });
88	
89	  test('adds a project, picks its status, and shows the status that was picked', async ({ page }) => {
90	    await resetAndSeed({
91	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
92	      projects: [],
93	    });
94	
95	    await page.goto('/projects');
96	    await expect(page.getByTestId('projects-empty')).toBeVisible();
97	
98	    const form = page.getByTestId('project-form');
99	    await expect(form).toBeVisible();
100	    await form.getByTestId('project-form-name').fill('Billing portal');
101	    await page.getByTestId('project-form-client').selectOption({ label: 'Acme Corp' });
102	
103	    // Pick a status that is NOT the likely default ("active"), so showing it proves the pick was
104	    // honoured rather than a fixed initial value being displayed.
105	    const status = page.getByTestId('project-form-status');
106	    await expect(status).toBeVisible();
107	    await pickStatus(status, HOLD);
108	
109	    await page.getByTestId('project-form-submit').click();
110	
111	    // RESTART IDENTITY on reset + no projects seeded => the created project is id 1.
112	    const row = page.getByTestId('project-row-1');
113	    await expect(row).toBeVisible();
114	    await expect(row.getByTestId('project-name')).toHaveText('Billing portal');
115	    await expect(row.getByTestId('project-client')).toHaveText('Acme Corp');
116	
117	    // It shows the on-hold status that was chosen — not active, not finished.
118	    await expect(row.getByTestId('project-status')).toContainText(HOLD);
119	    await expect(row.getByTestId('project-status')).not.toContainText(ACTIVE);
120	    await expect(row.getByTestId('project-status')).not.toContainText(FINISHED);
121	
122	    await expect(page.getByTestId('projects-empty')).toHaveCount(0);
123	  });
124	
125	  test('a project added as finished shows finished, proving the choice is not hardcoded', async ({ page }) => {
126	    await resetAndSeed({
127	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
128	      projects: [],
129	    });
130	
131	    await page.goto('/projects');
132	    await expect(page.getByTestId('project-form')).toBeVisible();
133	
134	    await page.getByTestId('project-form').getByTestId('project-form-name').fill('Archive import');
135	    await page.getByTestId('project-form-client').selectOption({ label: 'Acme Corp' });
136	    await pickStatus(page.getByTestId('project-form-status'), FINISHED);
137	    await page.getByTestId('project-form-submit').click();
138	
